// server/action/store.ts
function handleStore(ctx, session, requestedTab = "main") {
  const tab = requestedTab.replace(/_menu$/, "");
  const tabs = [["main", "Home", 0], ["locks", "Locks And Stuff", 1], ["bigitems", "Awesome Items", 4], ["weather", "Weather Machines", 5]];
  const active = tabs.some((t) => t[0] === tab) ? tab : "main";
  let ui = "set_description_text|Welcome to the Store! Select an item for details. Purchases use in-game Gems only.\nenable_tabs|1\n";
  for (const [key, label, icon] of tabs)
    ui += `add_tab_button|${key}_menu|${label}|interface/large/btn_shop.rttex||${active === key ? 1 : 0}|${icon}|0|0||||-1|-1|||0|0|CustomParams:|
`;
  for (const product of STORE_CATALOG) {
    if (active !== "main" && product.tab !== active) continue;
    if (product.items.some(([id]) => !ctx.itemsDb.get(id))) continue;
    if (product.key === "upgrade_backpack" && session.account.backpackSize >= 396) continue;
    const price = product.key === "upgrade_backpack" ? backpackPrice(session.account.backpackSize) : product.price;
    const description = product.key === "upgrade_backpack" ? "Adds 10 inventory slots. Maximum 396 slots." : product.items.map(([id, n]) => `${n} x ${ctx.itemsDb.get(id).name}`).join(", ");
    ui += `add_button|${product.key}|${product.name}|${product.texture}|${description}|${product.x}|${product.y}|${price}|0|||-1|-1||-1|-1||1||||||0|0|CustomParams:|
`;
  }
  session.peer.sendPacket(0, makeVariantPacket(["OnStoreRequest", ui]), true);
}

// server/action/buy.ts
function handleBuy(ctx, session, itemIdOrKey) {
  const key = String(itemIdOrKey).trim();
  if (["main", "locks", "bigitems", "weather"].includes(key.replace(/_menu$/, ""))) {
    handleStore(ctx, session, key);
    return;
  }
  const result = (message) => {
    session.peer.sendPacket(0, makeVariantPacket(["OnStorePurchaseResult", message]), true);
  };
  const product = STORE_CATALOG.find((p) => p.key === key);
  if (!product || product.items.some(([id]) => id === 6 || !ctx.itemsDb.get(id))) {
    result("This product is unavailable.");
    return;
  }
  const a = session.account, upgrade = key === "upgrade_backpack";
  if (upgrade && a.backpackSize >= 396) {
    result("Your backpack is already at maximum capacity.");
    return;
  }
  const price = upgrade ? backpackPrice(a.backpackSize) : product.price;
  if (!Number.isSafeInteger(a.gems) || a.gems < price) {
    result(`You need ${price} Gems for this product.`);
    return;
  }
  const inventory = a.inventory.map((s) => ({ ...s }));
  for (const [id, count] of product.items) {
    let slot = inventory.find((s) => s.itemId === id);
    if (slot ? slot.count + count > 200 : inventory.length >= a.backpackSize) {
      result("Not enough inventory space for the entire purchase.");
      return;
    }
    if (slot) slot.count += count;
    else inventory.push({ itemId: id, count, equipped: false });
  }
  const before = { inventory: a.inventory, gems: a.gems, backpackSize: a.backpackSize };
  a.inventory = inventory;
  a.gems -= price;
  if (upgrade) a.backpackSize = Math.min(396, a.backpackSize + 10);
  try {
    ctx.savePlayersNow();
  } catch {
    Object.assign(a, before);
    result("Purchase was not completed: storage error.");
    return;
  }
  recordProgress(ctx, session, "gems_spent", price);
  ctx.sendInventory(session, true);
  OnSetBux(session);
  result(`Purchased ${product.name} for ${price} Gems.`);
}

// server/action/dialog_return/drop_item.ts
function handleDropItemReturn(ctx, session, kv) {
  const world = session.world;
  if (!world) return;
  if (kv.buttonClicked === "Cancel") return;
  const itemId = parseInt((kv.itemID || "0").trim(), 10);
  const rawAmt = parseInt((kv.drop_count || "").trim(), 10);
  if (!itemId || itemId === 18 || itemId === 32 || !Number.isFinite(rawAmt) || rawAmt <= 0) {
    return;
  }
  const amt = Math.min(200, rawAmt);
  const slot = session.account.inventory.find((s) => s.itemId === itemId);
  if (!slot || slot.count < amt) {
    OnTextOverlay(session, "`4You don't have that many!``");
    return;
  }
  const playerTileX = Math.floor((session.x + 10) / 32);
  const playerTileY = Math.floor((session.y + 15) / 32);
  const targetTileX = Math.max(
    1,
    Math.min(world.width - 2, playerTileX + (session.facingLeft ? -1 : 1))
  );
  const targetTile = world.tiles[playerTileY * world.width + targetTileX];
  const targetFgDef = targetTile && targetTile.fg ? ctx.itemsDb.get(targetTile.fg) : void 0;
  if (targetFgDef && targetFgDef.collisionType === 1) {
    OnPlayPositioned(session, "audio/punch_locked.wav");
    OnTextOverlay(session, "You can't drop that here, face somewhere with open space.");
    return;
  }
  const dropX = targetTileX * 32 + 6;
  const dropY = playerTileY * 32 + 6;
  if (!ctx.consumeInventoryItem(session, itemId, amt, true)) return;
  spawnOrMergeWorldDrop(world, itemId, amt, dropX, dropY, session.netId);
  ctx.dirty = true;
}

